content.cssRule:
/* Min: 2rem, -> 3% screen, max: .w1 */
width: clamp(var(--space-8), 3vw, var(--space-12))
width: clamp(var(--space-8), 3dvw, var(--space-12))

/* Min: 2.5rem, -> 6% screen, max: .w2 */
width: clamp(var(--space-10), 6vw, var(--space-16))
width: clamp(var(--space-10), 6dvw, var(--space-16))

/* Min: 3rem, -> 10% screen, max: .w3 */
width: clamp(var(--space-12), 10vw, var(--space-20))
width: clamp(var(--space-12), 10dvw, var(--space-20))

background: linear-gradient(
		135deg,
		var(--color-secondary) 0%,
		var(--color-secondary-dark) 100%
	)
color: var(--color-text-alt)

background: linear-gradient(
		135deg,
		var(--green-500) 0%,
		var(--green-700) 100%
	)
color: var(--color-text-alt)

background: linear-gradient(
		135deg,
		var(--blue-500) 0%,
		var(--blue-700) 100%
	)
color: var(--color-text-alt)

background: linear-gradient(
		135deg,
		var(--yellow-500) 0%,
		var(--yellow-700) 100%
	)
color: var(--gray-900)

background: linear-gradient(
		135deg,
		var(--red-500) 0%,
		var(--red-700) 100%
	)
color: var(--color-text-alt)

/* Typography */
font-size: var(--font-size-s)
line-height: 1.5
/* Appearance */
color: var(--color-text-base)
/* Spacing */
padding: var(--space-3)
flex: 1

/* Typography */
font-size: var(--font-size-xs)
color: var(--gray-400)
/* Spacing */
padding: var(--space-1) var(--space-3) var(--space-2)

content.description:
@title Card accent variants
  @desc  Highlights only the left border with a semantic or palette color.
         Combine with .card. The other three borders become transparent.
  @example
    <div class="card card-accent-primary"><div class="card-body">...</div></div>
    <div class="card card-accent-success"><div class="card-body">...</div></div>
  @classes
    .card-accent-primary   | left border in primary color
    .card-accent-secondary | left border in secondary color
    .card-accent-tertiary  | left border in tertiary color
    .card-accent-success   | left border in success color
    .card-accent-warning   | left border in warning color
    .card-accent-error     | left border in error color

